CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Each thread computes one output element out[n, oc, ho, wo].
// Fuses 2x2 stride-2 average pool with bias-free 1x1 channel projection:
//   out[n,oc,ho,wo] = sum_ic w[oc,ic] * 0.25*(y[n,ic,2ho,2wo]+y[n,ic,2ho+1,2wo]+y[n,ic,2ho,2wo+1]+y[n,ic,2ho+1,2wo+1])
//
// Shared memory is used to stage the conv weight row for each output channel,
// and the 2x2 patch summation runs in registers to minimize global loads.

__global__ void pool_project_1x1_kernel(
    const float* __restrict__ y,       // (N, C_in, H, W)
    const float* __restrict__ w,       // (C_out, C_in)  -- view of (C_out, C_in, 1, 1)
    float* __restrict__ out,           // (N, C_out, Ho, Wo)  Ho=H/2, Wo=W/2
    int N, int C_in, int H, int W,
    int C_out, int Ho, int Wo
) {
    // Grid: (N * Ho * Wo) blocks along x, C_out blocks along y
    // Each block: blockDim.x threads handle a tile of output pixels for one output channel
    int oc = blockIdx.y;
    if (oc >= C_out) return;

    int out_hw = Ho * Wo;
    int pix_global = blockIdx.x * blockDim.x + threadIdx.x;
    int in_hw = H * W;

    // Cache the weight row for this output channel in shared memory
    // blockDim.x threads collaborate to load C_in weights
    extern __shared__ float sw[]; // size = C_in
    for (int ic = threadIdx.x; ic < C_in; ic += blockDim.x) {
        sw[ic] = w[oc * C_in + ic];
    }
    __syncthreads();

    if (pix_global >= N * out_hw) return;

    int n   = pix_global / out_hw;
    int rem = pix_global % out_hw;
    int ho  = rem / Wo;
    int wo  = rem % Wo;

    int hi0 = 2 * ho;
    int wi0 = 2 * wo;

    // Base pointer for this (n) in y
    const float* yn = y + n * C_in * in_hw;

    float acc = 0.0f;
    for (int ic = 0; ic < C_in; ++ic) {
        const float* yc = yn + ic * in_hw;
        float sum4 = yc[hi0 * W + wi0]
                   + yc[(hi0+1) * W + wi0]
                   + yc[hi0 * W + (wi0+1)]
                   + yc[(hi0+1) * W + (wi0+1)];
        acc += sw[ic] * sum4;
    }
    // multiply by 0.25 for the average
    out[n * C_out * out_hw + oc * out_hw + ho * Wo + wo] = acc * 0.25f;
}

torch::Tensor pool_project_1x1_cuda(
    torch::Tensor y,
    torch::Tensor conv_weight
) {
    int N    = y.size(0);
    int C_in = y.size(1);
    int H    = y.size(2);
    int W    = y.size(3);
    int C_out = conv_weight.size(0);
    int Ho = H / 2;
    int Wo = W / 2;

    auto out = torch::empty({N, C_out, Ho, Wo}, y.options());

    auto w2d = conv_weight.reshape({C_out, C_in}).contiguous();

    // One block per (oc) in y-dim; x-dim covers N*Ho*Wo pixels
    int pix_total = N * Ho * Wo;
    int block_x = 128;
    int grid_x  = (pix_total + block_x - 1) / block_x;

    dim3 grid(grid_x, C_out);
    dim3 block(block_x);
    size_t smem = C_in * sizeof(float);

    pool_project_1x1_kernel<<<grid, block, smem>>>(
        y.data_ptr<float>(),
        w2d.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C_in, H, W, C_out, Ho, Wo
    );

    return out;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    def __init__(self, num_input_features: int, num_output_features: int):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        """
                :param num_input_features: The number of input feature maps
                :param num_output_features: The number of output feature maps
                """
        self.transition = nn.Sequential(
                    nn.BatchNorm2d(num_input_features),
                    nn.ReLU(inplace=True),
                    nn.Conv2d(num_input_features, num_output_features, kernel_size=1, bias=False),
                    nn.AvgPool2d(kernel_size=2, stride=2)
                )
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        bn = self.transition[0]
        relu = self.transition[1]
        conv = self.transition[2]
        pool = self.transition[3]
        y = relu(bn(x))
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        if (y.is_cuda and y.dtype == torch.float32 and y.is_contiguous()
                        and y.size(2) % 2 == 0 and y.size(3) % 2 == 0):
                    return _stark_get_extension().pool_project_1x1(
                        y.contiguous(), conv.weight.contiguous()
